import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { sheetDueTotal, sheetOverdueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';

export const descendantsKey = (sheetId: string) => ['sheet', sheetId, 'descendants'] as const;

/** The sheet's descendants: its children (the sheets naming it as their parent), theirs, and so on. */
function useDescendants(sheetId: string) {
  return useQuery({
    queryKey: descendantsKey(sheetId),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`),
  });
}

type Figures = { people: number; due: string; overdue: string };

/** Adds the figures of sheets[at] (its people, and its due-total and overdue-total as its header shows them) to
 *  `sum`, then goes on to the next sheet; past the last, shows the figures added up. One component per sheet keeps
 *  each sheet's reads in hooks of its own. */
function Accumulate({ sheets, at, sum }: { sheets: string[]; at: number; sum: Figures }) {
  if (at >= sheets.length) return <Shown figures={sum} />;
  return <SheetFigures key={sheets[at]} sheets={sheets} at={at} sum={sum} />;
}

function SheetFigures({ sheets, at, sum }: { sheets: string[]; at: number; sum: Figures }) {
  const sheetId = sheets[at];
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const next: Figures = {
    people: sum.people + people.length,
    due: sumDue([sum.due, sheetDueTotal(people, claims, rates, today, floor, late, cap)]),
    overdue: sumDue([sum.overdue, sheetOverdueTotal(people, claims, rates, late, floor)]),
  };
  return <Accumulate sheets={sheets} at={at + 1} sum={next} />;
}

function Shown({ figures }: { figures: Figures }) {
  return (
    <p data-testid="consolidated">
      Consolidated: people <strong data-testid="consolidated-people-count">{figures.people}</strong>{' '}
      due total <strong data-testid="consolidated-due-total">{figures.due}</strong>{' '}
      overdue total <strong data-testid="consolidated-overdue-total">{figures.overdue}</strong>
    </p>
  );
}

/** Consolidated figures over the sheet and all its descendants: the people, and each sheet's due-total and
 *  overdue-total (as that sheet shows them) added up. A sheet with no children shows its own. */
function Consolidated({ sheetId }: { sheetId: string; user: string }) {
  const descendants = useDescendants(sheetId).data ?? [];
  return <Accumulate sheets={[sheetId, ...descendants]} at={0} sum={{ people: 0, due: '0.00', overdue: '0.00' }} />;
}

export const contribution = SheetBody.fill({ order: -1, Component: Consolidated });
EOF
